const axios = require("axios");

async function getData(packageName) {
  try {
    const response = await axios.get(
      `https://www.npmjs.com/search/suggestions?q=${packageName}`,
      {
        headers: {
          "x-csrf-token": "9wgGyEeUA-iPFXuLDfPn1Mp7OHuf5wQLlhDo9TEW_13",
          "accept": "application/json"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("kyzorohan")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
